pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTime, uint amount, uint depositAmount) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(depositAmount > 0 && depositAmount < 100 ether);
        vm.assume(amount <= depositAmount);
        vm.assume(amount >= 1 ether);

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put(unlockTime);

        uint snapshot = vm.snapshot();

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amount));

        if (success) {
            uint unlockTimeAfter = c.Acc(caller).unlockTime;
            assertTrue(unlockTimeAfter >= block.timestamp, "unlockTime should not be in the past after Collect");
        }

        vm.revertTo(snapshot);
    }
}

