pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0) && caller != address(this));
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Ensure the caller's balance is exactly MinSum after Put, and collectAmount equals exactly that balance
        uint256 minSum = c.MinSum();
        vm.assume(putAmount >= minSum);
        vm.assume(collectAmount == putAmount); // We'll use this to test the boundary

        // Now set the balance to be exactly collectAmount, then try to collect the same amount
        // For reference: acc.balance >= collectAmount allows it; buggy requires >
        vm.prank(caller);
        // We'll catch revert to see if Collect reverted
        bool reverted;
        try c.Collect{gas: 100000}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: if caller's balance == collectAmount and balance >= minSum and time condition met, Collect should NOT revert
        // For reference, it doesn't revert; for mutant, it reverts because balance > collectAmount is false.
        // We enforce the time condition:
        vm.warp(block.timestamp + 1); // ensure block.timestamp > unlockTime (assuming unlockTime <= current block.timestamp)
        // Actually we need to ensure unlockTime < block.timestamp. We can set unlockTime to 0 in Put call.
        // But we already set unlockTime via parameter. Better to vm.assume(unlockTime < block.timestamp)
        vm.assume(unlockTime < block.timestamp);

        // Re-issue the same call with correct time
        vm.prank(caller);
        try c.Collect{gas: 100000}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The invariant: if balance == collectAmount (i.e., _am equals balance), then Collect must NOT revert because >= is true.
        // The mutant breaks this by requiring >.
        assertTrue(!reverted, "Collect should not revert when balance == collectAmount");
    }
}

