pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 deposit, uint256 unlockTime, uint256 collectAmount) public {
        // Restrict inputs to realistic values
        vm.assume(user != address(0));
        deposit = bound(deposit, 1 ether, 10000 ether);
        collectAmount = bound(collectAmount, 1 ether, deposit);
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 365 days);

        // Fund the user and deposit into contract
        vm.deal(user, deposit);
        vm.prank(user);
        c.Put(unlockTime);

        // Advance time past unlock
        vm.warp(unlockTime + 1);

        // Attempt to collect exactly the balance
        uint256 balanceBefore = c.Acc(user).balance;
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Rule: If collecting exactly the balance, it should succeed (not revert)
        // because the reference allows acc.balance >= _am
        if (collectAmount == balanceBefore) {
            assertTrue(success, "Collecting exactly balance should not revert");
        }
    }
}

