pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 deposit, uint256 withdraw) public {
        vm.assume(user != address(0));
        vm.assume(deposit >= 1 ether);
        vm.assume(withdraw > 0);
        vm.assume(withdraw <= deposit);

        vm.deal(user, deposit);
        vm.prank(user);
        c.Put(block.timestamp);

        // Set unlock time to past so withdrawal is possible
        // We already called Put with block.timestamp, so unlockTime == block.timestamp
        // Wait one second to satisfy block.timestamp > unlockTime
        vm.warp(block.timestamp + 1);

        uint256 balanceBefore = c.Acc(user).balance;
        // withdraw might equal balance; in reference it succeeds, in bug it would revert when withdraw == balance
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", withdraw));
        if (withdraw == balanceBefore) {
            assertTrue(success, "Collect should succeed when withdrawing full balance");
        }
    }
}

